/* The second half of fn_1_28C0 (camera 1 + stage models + score view). Retail inlines fn_1_28C0 into
 * fn_1_6538 and fn_1_7450 but CW's auto-inline size limit refuses it written as one body; split
 * into this static inline, fn_1_28C0 stays emitted, raw=0, and both callers inline it (the split
 * point itself is a guess: any split that shrinks the body enough works). */
static inline void MgTourCam1Setup(void)
{
    Hu3DCameraCreate(HU3D_CAM1);
    Hu3DCameraPerspectiveSet(HU3D_CAM1, 1.2f, 15000, 40000, 1.2f);
    Hu3DCameraViewportSet(HU3D_CAM1, 0, 0, 640, 480, 0, 1);
    Hu3DCameraScissorSet(HU3D_CAM1, 0, 0, 640, 480);
    Hu3DCameraPosSet(HU3D_CAM1, 0, 100, 30000, 0, 1, 0, 0, 100, 0);
    Hu3DModelAttrSet(lbl_1_bss_16818->stageMdlId[5], HU3D_ATTR_DISPOFF);
    Hu3DModelAttrReset(lbl_1_bss_16818->stageMdlId[6], HU3D_ATTR_DISPOFF);
    Hu3DModelAttrReset(lbl_1_bss_16818->stageMdlId[4], HU3D_ATTR_DISPOFF);
    fn_1_C804();
    fn_1_D820(1, lbl_1_bss_16818->player);
    fn_1_CFEC(1);
}

